import pandas as pd

# Define the paths for all necessary data sources
data_sources = {
    'node_metrics': '/telemetry/row/metric/metric_node.parquet',
    'container_metrics': '/telemetry/row/metric/metric_container.parquet',
    'service_metrics': '/telemetry/row/metric/metric_service.parquet',
    'middleware_metrics': '/telemetry/row/metric/metric_middleware.parquet',
    'app_metrics': '/telemetry/row/metric/metric_app.parquet',
    'metric_stats': '/telemetry/metric_stats.parquet',
    'trace_spans': '/telemetry/row/trace/trace_span.parquet'
}

# Initialize a dictionary to store the status of each data source
data_status = {}

# Check the accessibility of each data source
for name, path in data_sources.items():
    try:
        # Attempt to read the data
        df = pd.read_parquet(path)
        data_status[name] = {'status': 'accessible', 'num_records': len(df)}
    except Exception as e:
        data_status[name] = {'status': 'not accessible', 'error': str(e)}

# Return the status of all data sources
data_status
